def claim_unlinked(unlinked, mode, amount):
    chosen = None
    chosen_idx = -1
    target = round(frappe.utils.flt(amount, 3), 3)
    for i in range(len(unlinked)):
        p = unlinked[i]
        if p.mode_of_payment == mode and round(frappe.utils.flt(p.paid_amount, 3), 3) == target:
            chosen = p
            chosen_idx = i
            break
    if chosen_idx >= 0:
        unlinked.pop(chosen_idx)
    return chosen

def claim_unlinked_je(unlinked_je, amount):
    chosen = None
    chosen_idx = -1
    target = round(frappe.utils.flt(amount, 3), 3)
    for i in range(len(unlinked_je)):
        p = unlinked_je[i]
        if round(frappe.utils.flt(p.total_debit, 3), 3) == target:
            chosen = p
            chosen_idx = i
            break
    if chosen_idx >= 0:
        unlinked_je.pop(chosen_idx)
    return chosen

def claim_manual(manual_pool, mode, amount):
    # Option A : match unique (mode + montant exact) d'un paiement manuel.
    # Retourne le candidat seulement s'il y en a EXACTEMENT un (sinon ambigu -> None).
    target = round(frappe.utils.flt(amount, 3), 3)
    hits = []
    for i in range(len(manual_pool)):
        p = manual_pool[i]
        if p["mode_of_payment"] == mode and round(frappe.utils.flt(p["paid_amount"], 3), 3) == target:
            hits.append(i)
    if len(hits) == 1:
        chosen = manual_pool[hits[0]]
        manual_pool.pop(hits[0])
        return chosen
    return None

