                    jes_to_delete.append(jm.name)
                regen_terms.append(term)
                continue

            if not matches:
                adopt = claim_unlinked(unlinked, term.mode_of_payment, term.payment_amount)
                if adopt:
                    frappe.db.set_value("Payment Entry", adopt.name, {"custom_source_row_uid": uid, "custom_source_fingerprint": fp}, update_modified=False)
                    adopted_uids[uid] = True
                    continue
                # Option A : adopter un paiement manuel (avance commande) de meme
                # mode et meme montant. 'Adopter' = taguer le PE existant (aucun
                # mouvement d'argent) pour qu'il devienne le paiement gere de
                # cette echeance. Match unique uniquement.
                madopt = claim_manual(manual_so_pool, term.mode_of_payment, term.payment_amount)
                if madopt:
                    frappe.db.set_value("Payment Entry", madopt["name"], {"custom_source_sales_order": doc.name, "custom_source_row_uid": uid, "custom_source_fingerprint": fp}, update_modified=False)
                    adopted_uids[uid] = True
                    continue

            locked = []
            free = []
            for pe_row in matches:
                if pe_is_locked(pe_row.paid_to, pe_row.mode_of_payment, ptt):
                    locked.append(pe_row)
                else:
                    free.append(pe_row)

            if locked:
                changed = False
                for lk in locked:
                    if lk.custom_source_fingerprint != fp:
                        changed = True
                if changed:
                    old = before_rows.get(uid)
                    if old:
                        frappe.db.set_value("Payment Schedule", term.name, {
                            "payment_amount": old.payment_amount,
                            "mode_of_payment": old.mode_of_payment,
                            "custom_banque": old.custom_banque,
                            "custom__n_chèque__transaction": old.custom__n_chèque__transaction,
                            "due_date": old.due_date,
                        }, update_modified=False)
                    frappe.msgprint("Echeance deja encaissee (PE " + locked[0].name + ") : modification ignoree. Passez par l'outil d'encaissement.")
                continue

            if len(free) == 1 and free[0].custom_source_fingerprint == fp:
                continue

            for pe_row in free:
                pes_to_delete.append(pe_row.name)
            regen_terms.append(term)

        orphan_locked = []
        for uid_key in pe_by_uid:
            if uid_key in seen:
                continue
            for pe_row in pe_by_uid[uid_key]:
                if pe_is_locked(pe_row.paid_to, pe_row.mode_of_payment, ptt):
                    orphan_locked.append(pe_row.name)
                    continue
                pes_to_delete.append(pe_row.name)
        for uid_key in je_by_uid:
            if uid_key in seen:
                continue
            for jm in je_by_uid[uid_key]:
                jes_to_delete.append(jm.name)

        mutated = bool(pes_to_delete) or bool(jes_to_delete) or bool(regen_terms)

        # Un PE deja encaisse (compte verrouille) rattache a une ligne SUPPRIMEE
        # reste alloue a la commande : regenerer par-dessus creerait un doublon et
        # ERPNext repondrait "a deja ete entierement paye". On bloque explicitement.
        if orphan_locked and regen_terms:
            frappe.msgprint(
                "Paiement deja encaisse (PE " + orphan_locked[0] + ") rattache a une ligne supprimee : "
                "regeneration ignoree. Passez par l'outil d'encaissement."
            )
            mutated = False

        # Factures validees liees a la commande : si la regeneration touche les
        # paiements, il faut aussi annuler/recreer la facture (le reglement est
        # souvent alloue a la facture, pas a la commande -> sans ca ERPNext
        # bloque avec "a deja ete entierement paye"). Les paiements deja
        # encaisses en banque (comptes verrouilles) bloquent la regeneration.
        invoices = []
        inv_pes_to_delete = []
        if mutated:
            inv_names = []
            for r in frappe.get_all("Sales Invoice Item",
                    filters={"sales_order": doc.name}, fields=["parent"]):
                if r.parent not in inv_names and frappe.db.get_value("Sales Invoice", r.parent, "docstatus") == 1:
                    inv_names.append(r.parent)
            locked_inv = False
            if inv_names:
                for ref in frappe.get_all("Payment Entry Reference",
                        filters={"reference_doctype": "Sales Invoice",
                                 "reference_name": ["in", inv_names], "docstatus": 1},
                        fields=["parent"]):
                    ped = frappe.db.get_value("Payment Entry", ref.parent,
                            ["name", "docstatus", "paid_to", "mode_of_payment"], as_dict=True)
                    if not ped or ped.docstatus != 1 or ped.name in pes_to_delete:
                        continue
                    # une « Dette non payée » n'est jamais un encaissement reel :
                    # toujours regenerable, quel que soit le compte (ex. Livraison
                    # Aramex avec un modele de termes devenu different).
                    if ped.mode_of_payment != "Dette non payée" and pe_is_locked(ped.paid_to, ped.mode_of_payment, ptt):
                        locked_inv = True
                    elif ped.name not in inv_pes_to_delete:
                        inv_pes_to_delete.append(ped.name)
            if locked_inv:
                frappe.msgprint("Facture deja encaissee en banque (compte verrouille) : la regeneration des paiements est ignoree. Passez par l'outil d'encaissement.")
                mutated = False
                inv_pes_to_delete = []
            else:
                invoices = inv_names

        if mutated:
            # Une echeance conservee dont le PE gere a ete realloue a une facture
            # qu'on annule doit AUSSI etre regeneree (sinon la facture perd ce
            # paiement). Les paiements MANUELS de la facture sont, eux, absorbes
            # via des slots de regeneration exacts.
            uid_by_pe = {}
            for p in pes:
                uid_by_pe[p.name] = p.custom_source_row_uid
            term_by_uid = {}
            for t in doc.payment_schedule:
                term_by_uid[t.custom_row_uid] = t
            regen_uids = {}
            for t in regen_terms:
                regen_uids[t.custom_row_uid] = True
            covered_uids = {}
            for uid_k in pe_by_uid:
                covered_uids[uid_k] = True
            for uid_k in adopted_uids:
                covered_uids[uid_k] = True

            # 1) PE geres conserves mais alloues a la facture -> regenerer leur echeance.
            for pe_name in inv_pes_to_delete:
                uid = uid_by_pe.get(pe_name)
                if uid and uid not in regen_uids:
                    t = term_by_uid.get(uid)
                    if t and t.mode_of_payment != "Avoir client":
                        regen_terms.append(t)
                        regen_uids[uid] = True

            # 2) Slots d'absorption = echeances regenerees SANS PE gere (elles
            #    existent pour reproduire un paiement non gere / manuel).
            slots = []
            for t in regen_terms:
                if t.custom_row_uid not in covered_uids:
                    slots.append(t)

            # 3) Chaque paiement MANUEL de la facture doit consommer un slot exact
            #    (mode + montant, mono-reference). Sinon -> abandon (paiement preserve).
            abort_manual = False
            for pe_name in inv_pes_to_delete:
                if uid_by_pe.get(pe_name):
                    continue
                mped = frappe.db.get_value('Payment Entry', pe_name, ['mode_of_payment', 'paid_amount'], as_dict=True)
                nrefs = frappe.get_all('Payment Entry Reference', filters={'parent': pe_name}, fields=['name'])
                claimed = False
                if mped and len(nrefs) == 1:
                    target = round(frappe.utils.flt(mped.paid_amount, 3), 3)
                    for i in range(len(slots)):
                        s = slots[i]
                        if s.mode_of_payment == mped.mode_of_payment and round(frappe.utils.flt(s.payment_amount, 3), 3) == target:
                            slots.pop(i)
                            claimed = True
                            break
                if not claimed:
                    abort_manual = True

            if abort_manual:
                frappe.msgprint("Un paiement manuel de la facture ne correspond a aucune echeance regeneree : regeneration ignoree. Passez par l'outil d'encaissement.")
                mutated = False

        if mutated:
            # 1) liberer la commande : paiements lies aux factures, factures, paiements traces
            for pe_name in inv_pes_to_delete:
                cancel_delete_pe(pe_name)
            for invoice in invoices:
                inv = frappe.get_doc("Sales Invoice", invoice)
                inv.flags.ignore_links = True
                inv.cancel()
            for pe_name in pes_to_delete:
                cancel_delete_pe(pe_name)
            for je_name in jes_to_delete:
                cancel_delete_je(je_name)

            # 2) recaler l'avance payee sur ce qui reste reellement alloue a la
            #    commande (sinon la validation "deja entierement paye" bloque).
            remaining = frappe.db.sql(
                """SELECT COALESCE(SUM(per.allocated_amount), 0)
                   FROM `tabPayment Entry Reference` per
                   INNER JOIN `tabPayment Entry` pe ON pe.name = per.parent
                   WHERE pe.docstatus = 1
                     AND per.reference_doctype = 'Sales Order'
                     AND per.reference_name = %s""", (doc.name,))[0][0]
            frappe.db.set_value("Sales Order", doc.name, "advance_paid",
                                frappe.utils.flt(remaining), update_modified=False)

            for term in regen_terms:
                fp = row_fingerprint(term)
                if term.mode_of_payment=="Avoir client":
                    create_avoir_journal_entry_for_sales_order(
                        customer=doc.customer,
                        company="Aquaworld & Servicing",
                        sales_order=doc.name,
                        amount=term.payment_amount,
                        receivable_account="Débiteurs - A&S",
                        src_uid=term.custom_row_uid,
                        src_fp=fp
                    )
                    continue
                pe = frappe.new_doc("Payment Entry")
                pe.flags.ignore_permissions = True
                pe.party_type = "Customer"


                pe.party = doc.customer
                pe.payment_type = "Receive"
                pe.mode_of_payment = term.mode_of_payment
                pe.company = "Aquaworld & Servicing"
                pe.paid_from = "Débiteurs - A&S"
                pe.paid_from_account_currency = "TND"
                if term.mode_of_payment=="Espèces":
                    pe.paid_to="Espèces - A&S"
                    if shared:
                        pe.paid_to=user_partener["economiqaquasolutions23@gmail.com"]
                    if shared_c or doc.owner=="yamen.fourati.2013@gmail.com":
                        pe.paid_to=user_contractor['yamen.fourati.2013@gmail.com']

                elif term.mode_of_payment=="Chèque":
                    pe.paid_to="Chèques - A&S"
                elif term.mode_of_payment=="Dette non payée" and doc.payment_terms_template=="Livraison Aramex":
                    pe.paid_to="Livraison Aramex - A&S"
                elif term.mode_of_payment=="Dette non payée":
                    pe.paid_to="Dettes - A&S"
                elif term.mode_of_payment=="Traite bancaire LC":
                    pe.paid_to="Traite Bancaire - A&S"
                elif term.mode_of_payment=="Retenue a la source vente":
                    pe.paid_to="Avance  impôt société - A&S"
                elif term.mode_of_payment=="Perte de paiement":
                    pe.paid_to="Perte de non paiement - A&S"
                    pe.cost_center="Principal - A&S"
                else:
                    pe.paid_to="STE430127B - Zitouna - A&S"



                # Routage partenaire : Especes / Cheque sur le compte partenaire
                # si la commande est partagee avec le partenaire.
                if term.mode_of_payment in ("Espèces", "Chèque") and shared:
                    pe.paid_to = user_partener["economiqaquasolutions23@gmail.com"]
                pe.paid_to_account_currency="TND"
                pe.posting_date = term.due_date
                pe.reference_no = doc.name
                pe.paid_amount = term.payment_amount
                pe.received_amount = term.payment_amount
                pe.source_exchange_rate=1
                pe.target_exchange_rate=1
                pe.base_paid_amount=1
                if term.custom__n_chèque__transaction is not None:
                    banque = term.custom_banque or ""
                    pe.reference_no = f"{term.custom__n_chèque__transaction}-{banque}".rstrip("-")

                if doc.payment_terms_template=="Livraison Aramex" and term.custom__n_chèque__transaction is not None:
                    pe.reference_no="Aramex N: "+term.custom__n_chèque__transaction
                doc.advance_paid=0
                #frappe.throw(doc.advance_paid)

                pe.reference_date=term.due_date
                payment_entry_ref = frappe.new_doc("Payment Entry Reference")
                payment_entry_ref.flags.ignore_permissions = True

                payment_entry_ref.reference_doctype = 'Sales Order'
                payment_entry_ref.reference_name = doc.name
                payment_entry_ref.allocated_amount = term.payment_amount
                payment_entry_ref.total_amount = term.payment_amount
                payment_entry_ref.outstanding_amount = term.payment_amount
                frappe.flags.ignore_permissions = True
                pe.flags.ignore_permissions = True
                pe.custom_source_row_uid = term.custom_row_uid
                pe.custom_source_fingerprint = fp
                pe.custom_source_sales_order = doc.name
                pe.insert(ignore_permissions=True)


                payment_entry_ref.parent = pe.name

                payment_entry_ref.docstatus=1
                payment_entry_ref.parenttype = "Payment Entry"
                payment_entry_ref.parentfield = "references"
                #frappe.throw(str(payment_entry_ref.outstanding_amount))

                payment_entry_ref.insert(ignore_permissions=True)
                pe.append("references", payment_entry_ref)
                pe.save(ignore_permissions=True)

                pe.submit()
        if mutated and invoices!=[]:
            unique_invoices=[]
            for invoice in invoices:
                if not (invoice in unique_invoices):
                    unique_invoices.append(invoice)
                    inv=frappe.get_doc("Sales Invoice",invoice)
                    new_invoice = frappe.copy_doc(inv)
                    new_invoice.allocate_advances_automatically=1
                    new_invoice.ignore_pricing_rule=1
                    new_invoice.only_include_allocated_payments=1
                    new_invoice.set_posting_time=1
                    new_invoice.posting_date=inv.posting_date
                    new_invoice.ignore_pricing_rule=1
                    new_invoice.items=[]
                    for item in inv.items:
                        is_free = (
                            frappe.utils.flt(item.discount_percentage) >= 100
                            or frappe.utils.flt(item.rate) == 0
                            or frappe.utils.flt(item.discount_amount) >= frappe.utils.flt(item.price_list_rate) * frappe.utils.flt(item.qty)
                        )
                        itemi = {
                        'item_code': item.item_code,
                        'qty': item.qty,
                        'rate': item.rate,
                        'sales_order': item.sales_order,
                        'delivery_note': item.delivery_note,
                        'is_free_item': 1 if is_free else 0
                        }
                        if is_free:
                            itemi.update({
                                "is_free_item": 1,
                                "discount_percentage": 100,
                                "discount_amount": 0,
                                "rate": 0,
                                "net_rate": 0,
                                "amount": 0,
                                "net_amount": 0,
                            })
                        new_invoice.append("items",itemi)

                    new_invoice.insert()

                    # Copier les pieces jointes de l'ancienne facture sur la
                    # nouvelle AVANT de supprimer l'ancienne (sinon le fichier
                    # physique serait supprime avec le dernier File qui le
                    # reference).
                    for fdoc in frappe.get_all("File",
                            filters={"attached_to_doctype": "Sales Invoice",
                                     "attached_to_name": inv.name},
                            fields=["file_url", "file_name", "is_private", "folder"]):
                        if not fdoc.file_url:
                            continue
                        nf = frappe.new_doc("File")
                        nf.file_url = fdoc.file_url
                        nf.file_name = fdoc.file_name
                        nf.is_private = fdoc.is_private
                        nf.folder = fdoc.folder
                        nf.attached_to_doctype = "Sales Invoice"
                        nf.attached_to_name = new_invoice.name
                        nf.flags.ignore_permissions = True
                        nf.insert(ignore_permissions=True)

                    new_invoice.ignore_default_payment_terms_template=1
                    new_invoice.payment_schedule=[]
                    new_invoice.payment_terms_template="Cash"
                    new_invoice.submit()
                    frappe.delete_doc("Sales Invoice", inv.name, ignore_permissions=True)
        # Nettoyage : apres reallocation des avances vers la facture recreee,
        # ERPNext laisse parfois une ligne de reference "Commande client" a 0.000
        # (l'avance drainee). On retire ces lignes residuelles pour ne garder que
        # la reference facture. Aucun impact comptable (montant alloue = 0).
        for zr in frappe.get_all("Payment Entry Reference",
                filters={"reference_doctype": "Sales Order", "reference_name": doc.name,
                         "allocated_amount": 0, "parenttype": "Payment Entry"},
                fields=["name", "parent"]):
            ped = frappe.db.get_value("Payment Entry", zr.parent, ["docstatus", "custom_source_sales_order"], as_dict=True)
            if ped and ped.docstatus == 1 and ped.custom_source_sales_order == doc.name:
                frappe.delete_doc("Payment Entry Reference", zr.name, ignore_permissions=True, force=True)

        # Resynchronisation finale, hors de tout "if mutated". Le script Before
        # Save "generer un echeancier de maintenace" remet advance_paid a 0 a
        # chaque sauvegarde ; si la regeneration n'a rien fait (garde-fou ou
        # aucune modification), personne ne le recale et la commande apparait
        # impayee alors que le paiement existe toujours.
        real_paid = frappe.utils.flt(frappe.db.sql(
            """SELECT COALESCE(SUM(per.allocated_amount), 0)
               FROM `tabPayment Entry Reference` per
               INNER JOIN `tabPayment Entry` pe ON pe.name = per.parent
               WHERE pe.docstatus = 1
                 AND per.reference_doctype = 'Sales Order'
                 AND per.reference_name = %s""", (doc.name,))[0][0])
        # Uniquement a la hausse : sur une commande facturee, le reglement est
        # alloue a la FACTURE et non a la commande (somme ci-dessus = 0), il ne
        # faut donc jamais abaisser advance_paid ici. Le seul cas a reparer est
        # celui ou la commande parait moins payee qu'elle ne l'est reellement.
        if real_paid > frappe.utils.flt(frappe.db.get_value("Sales Order", doc.name, "advance_paid")):
            frappe.db.set_value("Sales Order", doc.name, "advance_paid",
                                real_paid, update_modified=False)
    frappe.flags.ignore_permissions = False
if added_role:
    remove_temp_role(frappe.session.user)
